import{_ as l,l as s,o as a,c as i,v as t,p as n,x as r,d as u,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"mutex 与休眠","description":"","frontmatter":{"title":"mutex 与休眠","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mutex-sleep.md","filePath":"cs/mutex-sleep.md","lastUpdated":1789023840000}'),m={name:"cs/mutex-sleep.md"};function p(h,e,x,E,_,f){const o=s("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="mutex-与休眠" tabindex="-1">mutex 与休眠 <a class="header-anchor" href="#mutex-与休眠" aria-label="Permalink to &quot;mutex 与休眠&quot;">​</a></h1><div class="epigraph"><p>互斥锁在争用时把等待者挂到队列上并调度走；它有持有者概念，因而能做释放检查与优先级继承。</p><footer>—— 据 Love, Linux Kernel Development；Silberschatz et al. 整理</footer></div><p><a href="/cs/mcs-lock">上一课</a>把短等待做成可扩展自旋。临界区一旦可能等磁盘、或用户态可能被切走很久，忙等会烧光量子。缺口是 <strong>mutex</strong>：拿不到就睡眠，锁上记录持有者，释放时唤醒等待者。本课钉内核 mutex 与「禁在 IRQ 里拿」这条，不把 futex 系统调用写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自旋假设持有者正在别的核上跑临界区，很快会放。若持有者已睡眠，或临界区很长，等待者应进入<a href="/cs/runqueue">运行队列</a>之外的等待队列，让出 CPU。<a href="/cs/lock-irq">锁与关中断</a> 已说 ISR 不能拿睡眠锁：没有可调度的「之后」。缺口是把睡眠互斥做成带所有者的对象，而不是裸信号量计数。</p><p><span class="marginnote">所有者让「释放非持有者」可查，也让 PI 知道该 boost 谁。信号量没有所有者，V 谁都能做。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>快速路径：原子把锁从空闲改为当前任务。慢路径：自旋一小会儿（可选），然后关队列锁、把自身挂入、<code>schedule</code>。释放：清所有者，唤醒一个等待者。嵌套：同类 mutex 通常不可重入，除非明确是 recursive——主干默认不可重入，以免假装释放。</p>',8)),(a(),n(d,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRY%5B%22%E5%8E%9F%E5%AD%90%E5%BF%AB%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20GOT%5B%22%E8%8E%B7%E5%BE%97%22%5D%0A%20%20TRY%20--%3E%20SLEEP%5B%22%E5%85%A5%E7%AD%89%E5%BE%85%E9%98%9F%E5%88%97%E5%B9%B6%E8%B0%83%E5%BA%A6%22%5D%0A%20%20UNLOCK%5B%22%E9%87%8A%E6%94%BE%22%5D%20--%3E%20W%5B%22%E5%94%A4%E9%86%92%E4%B8%80%E4%BA%BA%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[u(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与<a href="/cs/kernel-preempt">内核抢占</a>：睡眠是自愿切换；持 mutex 时可以开抢占（与持自旋相反），但要防死锁与反转，PI 可叠加。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>mutex 把锁等待变成调度问题：等待者不算可运行，持有者能在没有自旋干扰下跑完（若没被更高级别挡住）。这改善吞吐，增加切换税。IRQ 与软中断仍禁止 <code>mutex_lock</code>。用户态 mutex 若每次争用都陷入，太重——下一课 futex 把未争用留在用户态。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 <code>ww_mutex</code> wound-wait 写完，不讨论 RT 把自旋改成睡眠的全面替换。读写锁、seqlock 更后。死锁仍可能：两把 mutex 互等。</p><p>后课默认：内核线程上下文用 mutex 睡眠。用户态未争用锁应避免陷入，下一课 futex。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>mutex：有所有者，争用则睡；禁止 IRQ 上下文。</li><li>持锁时可抢占，与自旋相反；可接 PI。</li><li>用户态快路径是 futex。</li><li>出处：Love, <em>LKD</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',8))])}const T=l(m,[["render",p]]);export{A as __pageData,T as default};
